function curioidRgbToOklab(r,g,b){
    const linear=value=>{const c=clamp(Number(value)/255,0,1);return c<=0.04045?c/12.92:Math.pow((c+0.055)/1.055,2.4);};
    r=linear(r);g=linear(g);b=linear(b);
    const l=Math.cbrt(0.4122214708*r+0.5363325363*g+0.0514459929*b);
    const m=Math.cbrt(0.2119034982*r+0.6806995451*g+0.1073969566*b);
    const s=Math.cbrt(0.0883024619*r+0.2817188376*g+0.6299787005*b);
    return [0.2104542553*l+0.793617785*m-0.0040720468*s,1.9779984951*l-2.428592205*m+0.4505937099*s,0.0259040371*l+0.7827717662*m-0.808675766*s];
  }

function curioidOklabToRgb(L,a,b){
    const l=Math.pow(L+0.3963377774*a+0.2158037573*b,3),m=Math.pow(L-0.1055613458*a-0.0638541728*b,3),s=Math.pow(L-0.0894841775*a-1.291485548*b,3);
    const gamma=value=>{const c=clamp(value,0,1);return Math.round(255*(c<=0.0031308?12.92*c:1.055*Math.pow(c,1/2.4)-0.055));};
    return [gamma(4.0767416621*l-3.3077115913*m+0.2309699292*s),gamma(-1.2684380046*l+2.6097574011*m-0.3413193965*s),gamma(-0.0041960863*l-0.7034186147*m+1.707614701*s)];
  }

function curioidClusterPalette(rgbPixels,maxColors=8,iterations=8){
    const samples=[];
    for(const pixel of Array.isArray(rgbPixels)?rgbPixels:[]){if(!Array.isArray(pixel)||pixel.length<3)continue;const rgb=pixel.slice(0,3).map(Number);if(!rgb.every(value=>Number.isFinite(value)&&value>=0&&value<=255))continue;samples.push({lab:curioidRgbToOklab(...rgb)});}
    if(!samples.length)return [];
    const target=Math.max(1,Math.min(8,Math.floor(Number(maxColors)||8))),rounds=Math.max(1,Math.min(16,Math.floor(Number(iterations)||8)));
    const mean=[0,0,0];for(const item of samples)for(let axis=0;axis<3;axis++)mean[axis]+=item.lab[axis]/samples.length;
    const centers=[mean];
    while(centers.length<target){let farthest=null,best=-1;for(const item of samples){let nearest=Infinity;for(const center of centers){const d=(item.lab[0]-center[0])**2+(item.lab[1]-center[1])**2+(item.lab[2]-center[2])**2;if(d<nearest)nearest=d;}if(nearest>best){best=nearest;farthest=item.lab;}}if(!farthest||best<1e-7)break;centers.push(farthest.slice());}
    let counts=new Array(centers.length).fill(0);
    for(let pass=0;pass<rounds;pass++){
      const sums=centers.map(()=>[0,0,0]);counts=new Array(centers.length).fill(0);
      for(const item of samples){let chosen=0,best=Infinity;for(let index=0;index<centers.length;index++){const center=centers[index],lab=item.lab,d=(lab[0]-center[0])**2+(lab[1]-center[1])**2+(lab[2]-center[2])**2;if(d<best){best=d;chosen=index;}}counts[chosen]++;for(let axis=0;axis<3;axis++)sums[chosen][axis]+=item.lab[axis];}
      for(let index=0;index<centers.length;index++)if(counts[index])centers[index]=sums[index].map(value=>value/counts[index]);
    }
    return centers.map((lab,index)=>({rgb:curioidOklabToRgb(...lab),count:counts[index]})).filter(item=>item.count>0).sort((a,b)=>b.count-a.count).map(item=>({hex:'#'+item.rgb.map(value=>value.toString(16).padStart(2,'0')).join(''),count:item.count}));
  }

