      if(url.origin!==window.location.origin)script.crossOrigin='anonymous';
      script.crossOrigin='anonymous';script.setAttribute('data-cfasync','false');script.integrity='sha384-UMHql2JfOtC9mM3xy+YD7CiQk9sSGlziW9AK6as8lEn/XhIba37+0MbLFPO5SPE/';script.referrerPolicy='strict-origin-when-cross-origin';script.src=url.href;script.async=true;
