    async function initialiseCDrive(){try{driveDb=await openDriveDatabase();if(driveDb.objectStoreNames.contains('handles')){await new Promise(resolve=>{try{const tx=driveDb.transaction('handles','readwrite');tx.objectStore('handles').clear();tx.oncomplete=resolve;tx.onerror=resolve;tx.onabort=resolve;}catch(_){resolve();}});}const all=await dbGetAllItems();if(all.length){driveFallbackReadOnly=false;driveFallbackIssues.length=0;virtualFiles=[];virtualRecycleBin=[];driveFingerprints=new Map();all.forEach(record=>{const state=record._state==='returned'||record.deletedAt?'returned':'active';const f=normalizeDriveItem(record);driveFingerprints.set(f.id,driveFingerprint(record,state));if(record.blob)driveBlobs.set(f.id,record.blob);delete f.blob;delete f._state;if(state==='returned')virtualRecycleBin.push(f);else virtualFiles.push(f);});const filesRaw=JSON.stringify(cacheDriveItems(virtualFiles)),recycleRaw=JSON.stringify(cacheDriveItems(virtualRecycleBin));if(safeSet(filesKey,filesRaw))driveFallbackRaw.set(filesKey,filesRaw);if(safeSet(recycleKey,recycleRaw))driveFallbackRaw.set(recycleKey,recycleRaw);}else{if(!driveFallbackReadOnly)await persistDriveSnapshot();else driveError=`C: recovery required. ${driveFallbackIssues.join(' ')}`;}if(!driveFallbackReadOnly)driveError='';}catch(error){driveDb=null;driveError=driveFallbackReadOnly?`C: recovery required. ${driveFallbackIssues.join(' ')}`:`IndexedDB unavailable: ${error?.message||'unknown error'}. The system is using the smaller browser-storage fallback.`;}driveLastQuotaAccepted=driveCaptureState();const existingQuotaError=curioidDoors98DriveQuotaError(driveCurrentRecords());if(existingQuotaError)driveError=existingQuotaError;return true;}
