        if(quotaError){driveCrossTabConflict=true;driveError=`Another tab's saved changes exceed the shared C: budget. ${quotaError}`;driveNotifyFailure(driveError);return;}
        driveFingerprints=new Map(actual.map(record=>[record.id,driveFingerprint(record,record._state==='returned'||record.deletedAt?'returned':'active')]));
