    const DOORS_APP_ID_STORAGE=new Map();
    function readDoorAppIds(key,limit=100){
      let raw=null;
      try{raw=localStorage.getItem(key);if(raw===null){DOORS_APP_ID_STORAGE.set(key,{raw:null,readOnly:false,reason:''});return[];}if(typeof raw!=='string'||raw.length>16384)throw new Error('The saved application shortcut list exceeds its safe size limit.');const value=JSON.parse(raw);if(!Array.isArray(value)||value.length>500||value.some(id=>typeof id!=='string'||!Object.prototype.hasOwnProperty.call(appNames,id)))throw new Error('The saved application shortcut list is malformed or contains an unknown application.');DOORS_APP_ID_STORAGE.set(key,{raw,readOnly:false,reason:''});return[...new Set(value)].slice(0,limit);}
      catch(error){DOORS_APP_ID_STORAGE.set(key,{raw,readOnly:true,reason:String(error?.message||error).slice(0,180)});return[];}
    }
    function classifyDoorsShortcutWriteOutcome(key,previous,serialized){
      try{
        const current=localStorage.getItem(key);
        if(current===serialized)return{state:'committed',current};
        if(current===previous)return{state:'unchanged',current};
        return{state:'conflict',current};
      }catch(error){return{state:'unreadable',current:null,error};}
    }
    function writeDoorAppIds(key,values){
      const state=DOORS_APP_ID_STORAGE.get(key);if(!state||state.readOnly){toast(null,`Application shortcuts are read-only because their original data could not be verified. ${state?.reason||'Reload when browser storage is available.'} No data was overwritten.`);return false;}
      if(!Array.isArray(values)||values.length>(key===DOORS_APP_FAVORITES_KEY?100:18)||values.some(id=>typeof id!=='string'||!Object.prototype.hasOwnProperty.call(appNames,id))){toast(null,'CURIOID refused an invalid application-shortcut update.');return false;}
      const serialized=JSON.stringify([...new Set(values)]);let previous;
      try{previous=localStorage.getItem(key);if(previous!==state.raw){state.readOnly=true;state.reason='The shortcut list changed in another tab. Reload before editing.';toast(null,state.reason);return false;}localStorage.setItem(key,serialized);if(localStorage.getItem(key)!==serialized)throw new Error('The saved shortcut list failed read-back verification.');state.raw=serialized;return true;}
      catch(error){const outcome=classifyDoorsShortcutWriteOutcome(key,previous,serialized);if(outcome.state==='committed'){state.raw=serialized;state.readOnly=false;state.reason='';return true;}if(outcome.state!=='unchanged'){state.readOnly=true;state.reason=outcome.state==='conflict'?'The shortcut list changed in another tab. The newer list was preserved; reload before editing.':'Current shortcut storage could not be inspected. No rollback was attempted.';toast(null,`Application shortcut storage needs recovery. ${state.reason}`);return false;}toast(null,`Application shortcut was not saved. The previous list remains intact: ${String(error?.message||error).slice(0,120)}`);return false;}
    }
