        'daily-journal':`<div class="retro-work-app retro-journal"><header><small>WORKSHOP / PRIVATE WRITING</small><h3>Daily Journal</h3><p>A quiet place for daily entries, project notes and thoughts. Entries are stored locally on C:.</p></header><form data-journal-form><label>Date <input type="date" name="date" required></label><label>Entry title <input name="title" maxlength="100" required placeholder="A little title"></label><label>Your entry <textarea name="body" rows="7" maxlength="30000" placeholder="Write freely…"></textarea></label><div class="retro-work-toolbar"><button type="submit">Save entry to C:</button><button type="button" data-journal-export>Export journal</button></div></form><div data-journal-list class="retro-journal-list"></div><p data-journal-status>Entries remain in your browser's virtual C: drive.</p></div>`,
        'reading-list':`<div class="retro-work-app retro-reading-list"><header><small>RECEPTION / LATER, PERHAPS</small><h3>Reading List</h3><p>Collect article addresses and notes as references. CURIOID does not open public websites.</p></header><form data-reading-form><label>Page title <input name="title" maxlength="120" placeholder="A useful page"></label><label>Address <input name="url" type="url" required placeholder="https://example.com"></label><label>Note <input name="note" maxlength="240" placeholder="Why did you save this?"></label><button type="submit">Save reading key</button></form><div data-reading-items class="retro-reading-items"></div><p data-reading-status>Stored in C: / Reception.</p></div>`,
