          const target=event.target;
          if(target?.closest?.('input,textarea,select,[contenteditable="true"]'))return;
          const clipboard=event.clipboardData;
          const files=Array.from(clipboard?.files||[]);
          if(!files.length){
            const fromItems=Array.from(clipboard?.items||[]).filter(item=>item.kind==='file').map(item=>item.getAsFile()).filter(Boolean);
            files.push(...fromItems);
          }
          if(files.length){event.preventDefault();event.stopImmediatePropagation();importExternalFilesToC(files).catch(error=>setStatus(error.message));return;}
