      bellaCharacter?.addEventListener('pointerdown',/** @param {CurioidDOMEvent} e */ e=>{if(bellaMode!=='avatar'||e.button!==0||!bellaPanel||bellaPanel.hidden||!bellaDesktop)return;const desk=bellaDesktop.getBoundingClientRect(),box=bellaPanel.getBoundingClientRect(),positioned=bellaPanel.classList.contains('bella-user-positioned');bellaDrag={pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,left:positioned?(parseFloat(bellaPanel.style.left)||box.left-desk.left):box.left-desk.left,top:positioned?(parseFloat(bellaPanel.style.top)||box.top-desk.top):box.top-desk.top,moved:false};bellaCharacter.setPointerCapture?.(e.pointerId);bellaCharacter.style.cursor='grabbing';});
