            wave:[{transform:'rotate(0) translateY(0)'},{transform:'rotate(-7deg) translateY(-5px)',offset:.3},{transform:'rotate(6deg) translateY(-8px)',offset:.62},{transform:'rotate(0) translateY(0)'}],
