            wiggle:[{transform:'rotate(0)'},{transform:'rotate(-6deg)',offset:.22},{transform:'rotate(6deg)',offset:.44},{transform:'rotate(-4deg)',offset:.66},{transform:'rotate(3deg)',offset:.84},{transform:'rotate(0)'}],
            peek:[{transform:'translateX(0) scale(1)'},{transform:'translateX(8px) scale(.98)',offset:.5},{transform:'translateX(0) scale(1)'}],
            dozy:[{transform:'translateY(0) rotate(0)'},{transform:'translateY(4px) rotate(3deg)',offset:.5},{transform:'translateY(0) rotate(0)'}],
            listening:[{transform:'scale(1)'},{transform:'scale(1.035)',offset:.45},{transform:'scale(1)'}],
            stretch:[{transform:'translateY(0) scale(1,1)'},{transform:'translateY(3px) scale(1.02,.93)',offset:.22},{transform:'translateY(-7px) scale(.97,1.1)',offset:.6},{transform:'translateY(0) scale(1,1)'}],
            nod:[{transform:'rotate(0) translateY(0)'},{transform:'rotate(3deg) translateY(3px)',offset:.28},{transform:'rotate(-2deg) translateY(-1px)',offset:.56},{transform:'rotate(0) translateY(0)'}],
