      function bellaAdd(role,text,save=true){const clean=String(text||'').trim().slice(0,1800);if(!clean)return;bellaHistory.push({role,text:clean});bellaHistory=bellaHistory.slice(-32);bellaRenderHistory();if(save)bellaPersist();if(role==='bella'){bellaLastInteraction=Date.now();if(bellaCharacter&&bellaMotionAllowed()){bellaCharacter.classList.add('bella-speaking');clearTimeout(bellaSpeakingTimer);bellaSpeakingTimer=setTimeout(()=>bellaCharacter?.classList.remove('bella-speaking'),Math.min(5200,Math.max(1200,clean.length*25)));}bellaAnimate('happy',1450);}}
      let bellaLastToneAddon='';
      function bellaTone(text){
        const voices={
          concierge:{open:['Of course.','Certainly.','Right away.'],close:['I am right here at the desk.','Happy to help.']},
          playful:{open:['Ooh, alright!','Aha!','Now we are talking.'],close:['Tiny bell, big enthusiasm.','I shall try not to over-celebrate.']},
          precise:{open:['Understood.','Clear enough.','Right.'],close:['That is the result.','No extra fuss.']},
          cozy:{open:['Of course, dear.','Absolutely.','Take your time.'],close:['No rush at all.','One little step at a time.']},
          mysterious:{open:['The building has heard you.','Curious.','The corridor stirs.'],close:['The doors are listening.','We shall see what answers.']},
          curious:{open:['Oh, interesting.','Now I am curious.','Let us investigate.'],close:['What do you think?','There may be another angle.']},
          nerdy:{open:['A delightful systems problem.','Let us inspect the details.','Excellent question.'],close:['I have mentally labelled the diagram.','That is my current hypothesis.']},
          witty:{open:['Naturally.','Well, look at that.','I was almost prepared for this.'],close:['I shall file that under useful discoveries.','The handbook grows stranger.']},
          encouraging:{open:['You have got this.','Absolutely.','We can work through it.'],close:['One step at a time.','You are making progress.']}
        };
        const voice=voices[bellaPersona]||voices.concierge;
        let output=String(text||'').trim();
        if(Math.random()<.22){const options=voice.open.filter(item=>item!==bellaLastToneAddon);const addon=options[Math.floor(Math.random()*Math.max(1,options.length))]||voice.open[0];bellaLastToneAddon=addon;output=`${addon} ${output}`;}
        if(Math.random()<.07){const options=voice.close.filter(item=>item!==bellaLastToneAddon);const addon=options[Math.floor(Math.random()*Math.max(1,options.length))]||voice.close[0];bellaLastToneAddon=addon;output=`${output} ${addon}`;}
        return output;
      }
      function bellaReply(text){const reply=bellaTone(text);bellaAdd('bella',reply);if(bellaVoiceEnabled&&bellaCompanionOn&&!bellaPanel?.hidden){const voice=bellaPersonas[bellaPersona]||bellaPersonas.concierge;bellaSpeech.speak(reply,{lang:'en-US',rate:voice.rate,pitch:voice.pitch,volume:.78});}}
      function bellaSyncToggle(opening){bellaToggle?.setAttribute('aria-expanded',String(opening));bellaToggle?.setAttribute('aria-pressed',String(opening));bellaToggle?.setAttribute('aria-label',opening?'Dismiss Bella assistant':'Call Bella assistant');bellaToggle?.classList.toggle('bella-active',opening);bellaToggle?.classList.toggle('bella-ringing',opening);}
      let bellaVisualAnimations=[],bellaGestureAnimation=null,bellaVisualTimers=[];
