        if(rememberMatch){const fact=rememberMatch[1].trim().slice(0,240);if(fact){bellaMemory=bellaMemory.filter(x=>bellaNormalize(x)!==bellaNormalize(fact));bellaMemory.unshift(fact);bellaMemory=bellaMemory.slice(0,16);safeSet(bellaMemoryKey,JSON.stringify(bellaMemory));bellaReply(`I’ll keep that in my little local notebook: “${fact}”. You can ask what I remember or tell me to forget it. This memory stays in this browser.`);}return;}
        if(/^(what do you remember|what have you learned about me|show your memories)/.test(commandQ)){bellaReply(bellaMemory.length?`My local notebook has ${bellaMemory.length} note${bellaMemory.length===1?'':'s'} you explicitly asked me to remember:\n• ${bellaMemory.join('\n• ')}\nSay “forget [words]” to remove a note, or “forget everything” to clear them.`:'My notebook is blank so far. Say “remember that…” and I’ll save a small note in this browser only.');return;}
        if(/^(forget everything|forget all memories|clear your memories)$/.test(commandQ)){bellaMemory=[];safeSet(bellaMemoryKey,'[]');bellaReply('My local notebook is clear. Our conversation history is separate; use Clear conversation to remove that too.');return;}
        const forgetMatch=commandMessage.match(/^(?:please )?forget\s+(.+)$/i);if(forgetMatch){const needle=bellaNormalize(forgetMatch[1]);const before=bellaMemory.length;bellaMemory=bellaMemory.filter(x=>!bellaNormalize(x).includes(needle));safeSet(bellaMemoryKey,JSON.stringify(bellaMemory));bellaReply(before===bellaMemory.length?'I could not find a saved note matching that.':'Done. I removed the matching note from my local notebook.');return;}
