      if(state.known.length>=MAX_FOOD_RECORDS||Object.keys(state.items).length>=MAX_FOOD_RECORDS||Object.keys(state.pairs).length>=MAX_FOOD_PAIRS){updateStatus('The local cookbook has reached its safe record limit. Export a backup and remove older discoveries before adding more.');return{failedCapacity:true};}
      const curatedRule=foodFusionRules[pair],rule=curatedRule||generatedFoodRule(a,b),depth=Math.max(Number(a.depth)||0,Number(b.depth)||0)+1;
      const rarity=rule?.rarity||(()=>{let n=0;for(let i=0;i<pair.length;i++)n=(n*31+pair.charCodeAt(i))>>>0;const roll=n%100;return depth>=4&&roll<8?'rare':roll<27?'uncommon':'common';})();
      const pairHash=(()=>{let h=2166136261;for(let i=0;i<pair.length;i++)h=Math.imul(h^pair.charCodeAt(i),16777619)>>>0;return h.toString(36);})();
      const id=rule?.id||`${rule?'recipe-concept-':'experiment-'}${pairHash}`;
