      const name=cleanText(rule?.name||`Experiment: ${names[0]} + ${names[1]}`,100);
      const kind=rule?.kind||'experiment',family=rule?(kind==='dish'?'dish':'prepared'):'experiment';
      const summary=rule?.summary||`An unverified pairing of ${names[0]} and ${names[1]}. It is saved as a kitchen experiment, not presented as a tested dish or recipe.`;
