      if(id==='recipes')body=`<div class="food-os-app-toolbar"><input type="search" data-food-recipe-search placeholder="Search recipes and discoveries…"><span data-food-recipe-count>${recipeList().length} DISCOVERIES</span></div><div class="food-os-recipes-layout"><div class="food-os-recipes-list" data-food-recipes-list></div><div class="food-os-recipe-detail-host" data-food-recipe-detail-host><div class="food-os-empty-detail"><span>📖</span><b>Your cookbook</b><p>Select a recipe to inspect its ingredients and method.</p></div></div></div><div class="food-os-backup-actions"><button type="button" data-food-export>Export cookbook backup</button><label>Import backup<input type="file" data-food-import accept="application/json,.json"></label></div>`;
      if(id==='timer')body=`<div class="food-os-timer"><span class="food-os-eyebrow">KITCHEN TIMER / LOCAL</span><div class="food-os-timer-display" data-food-timer-display>05:00</div><div class="food-os-timer-presets"><button type="button" data-food-timer-preset="3">3 min</button><button type="button" data-food-timer-preset="5">5 min</button><button type="button" data-food-timer-preset="10">10 min</button><button type="button" data-food-timer-preset="20">20 min</button></div><label class="food-os-timer-custom">Minutes <input type="number" min="1" max="180" value="5" data-food-timer-minutes></label><div class="food-os-timer-controls"><button type="button" class="food-os-primary-action" data-food-timer-start>Start</button><button type="button" data-food-timer-pause>Pause</button><button type="button" data-food-timer-reset>Reset</button></div><p data-food-timer-status>Timer is ready.</p></div>`;
      if(id==='shopping')body=`<form class="food-os-add-form" data-food-shopping-form><input type="text" data-food-shopping-input maxlength="100" placeholder="Add something to buy…" aria-label="Shopping list item"><button type="submit">+ Add</button></form><div class="food-os-shopping-list" data-food-shopping-list></div><div class="food-os-shopping-footer"><span data-food-shopping-count>0 ITEMS</span><button type="button" data-food-shopping-clear>Clear completed</button></div>`;
