      const list=win.querySelector('[data-food-journal-list]');if(list){const entries=state.log.map((entry,index)=>({entry,index})).slice(-25).reverse();list.innerHTML=entries.length?entries.map(({entry:x,index})=>{const a=getItem(x.a),b=getItem(x.b),r=getItem(x.result);return `<div class="food-os-journal-row"><span>${foodEmoji(r)}</span><span><b>${esc(r?.name||x.result)}</b><small>${esc(a?.name||x.a)} + ${esc(b?.name||x.b)}</small></span><time>${new Date(x.at).toLocaleDateString()}</time><button type="button" class="food-os-delete-button" data-food-delete-log="${index}" aria-label="Remove journal entry">×</button></div>`;}).join(''):'<p class="food-os-muted">No experiments yet. The first discovery is waiting.</p>';}
