      const flavor=win.querySelector('[data-food-market-flavor]'),rate=win.querySelector('[data-food-market-rate]');if(flavor)flavor.textContent=foodFormatFlavor(game.flavor);if(rate)rate.textContent=`+${foodFlavorRate()<10?foodFlavorRate().toFixed(1):foodFormatFlavor(foodFlavorRate())} Flavor / sec`;
      const level=win.querySelector('[data-food-line-cook-level]'),lineButton=win.querySelector('[data-food-buy-line-cook]'),lineCost=FOOD_LINE_COOK_COSTS[game.lineCookLevel];if(level)level.textContent=`LEVEL ${game.lineCookLevel} / ${FOOD_LINE_COOK_COSTS.length}`;if(lineButton){lineButton.textContent=lineCost===undefined?'Maximum level reached':`Upgrade · ${foodFormatFlavor(lineCost)} Flavor`;lineButton.disabled=lineCost===undefined||game.flavor<lineCost;}
