    const removeLexiconCapabilities=()=>{['echonoise.lexicon.analyze','echonoise.lexicon.lookup','echonoise.lexicon.compare','echonoise.lexicon.palette','echonoise.lexicon.rhymes','echonoise.lexicon.stress-match','echonoise.lexicon.fingerprint','echonoise.lexicon.phoneme-search'].forEach(id=>CurioidKernel.unregisterCapability(id,'echonoise-os'));if(window.CurioidLexicon?.version==='3.0.0')delete window.CurioidLexicon;};
    function updateClock(){const n=new Date(),time=n.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}),date=n.toLocaleDateString([], {weekday:'long',year:'numeric',month:'long',day:'numeric'});const clock=$e('[data-eno-clock]'),tray=$e('[data-eno-tray-clock]'),topDate=$e('[data-eno-date]'),d=$e('[data-eno-clock-date]'),t=$e('[data-eno-clock-time]');if(clock)clock.textContent=n.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});if(tray)tray.textContent=time;if(topDate)topDate.textContent=n.toLocaleDateString([], {weekday:'short',month:'short',day:'numeric'}).toUpperCase();if(d)d.textContent=date;if(t)t.textContent=time;}
    restore();applyTheme(safeGet('curioid-echonoise-theme-v1','neon'));syncUI();renderSteps();renderPatternBanks();updateClock();syncMuteButton();updateTaskbar();setMasterVolume(masterVolume*100);
    try{clockRelease=runtime?.interval?.(updateClock,1000)||null;}catch(_){}
    if(!clockRelease)clockTimer=setInterval(updateClock,1000);
    const onCurioidOpenApp=e=>{if(e.detail?.id==='lexicon')openApp('lexicon');};
    const onVisibilityChange=()=>{if(document.hidden&&audio)hardStopAudio();};
    const onPageHide=()=>hardStopAudio();
    document.addEventListener('visibilitychange',onVisibilityChange);window.addEventListener('pagehide',onPageHide,{once:true});
    enoShell.addEventListener('curioid:open-app',onCurioidOpenApp);
    const ARCADE_STATS_KEY='curioid-echonoise-arcade-stats-v1';
    const arcadeLabels={six:'Rhythm Grid',center:'Center Guard',interval:'Interval Ear',chord:'Chord Ear'};
    const arcadeStats=(()=>{try{const value=JSON.parse(safeGet(ARCADE_STATS_KEY,'{}'));return value&&typeof value==='object'&&!Array.isArray(value)?value:{ };}catch(_){return{};}})();
    let arcadeMode='six',arcadeGame=null,arcadeRAF=0,arcadeWindow=null,arcadeQuiz=null;
    const arcadeDifficulty={
      'very-easy':{step:2,probability:.62,window:.23,travel:2.15},
      easy:{step:1,probability:.66,window:.19,travel:1.8},
      normal:{step:.5,probability:.57,window:.15,travel:1.55},
      hard:{step:.5,probability:.82,window:.12,travel:1.35},
      expert:{step:.25,probability:.73,window:.095,travel:1.2},
      impossible:{step:.25,probability:.94,window:.065,travel:1.0}
    };
    const arcadeIntervals=[['Minor 2nd',1],['Major 2nd',2],['Minor 3rd',3],['Major 3rd',4],['Perfect 4th',5],['Tritone',6],['Perfect 5th',7],['Minor 6th',8],['Major 6th',9],['Minor 7th',10],['Major 7th',11],['Octave',12]];
    const arcadeChords=[['Major',[0,4,7]],['Minor',[0,3,7]],['Diminished',[0,3,6]],['Augmented',[0,4,8]],['Suspended 2',[0,2,7]],['Suspended 4',[0,5,7]],['Minor 7th',[0,3,7,10]],['Major 7th',[0,4,7,11]],['Dominant 7th',[0,4,7,10]]];
    function arcadeTone(midi,when=0,duration=.24,level=.1){const a=makeAudio();if(!a)return;const ctx=a.ctx,at=Math.max(ctx.currentTime+.008,when||ctx.currentTime+.008),osc=ctx.createOscillator(),amp=ctx.createGain(),filter=ctx.createBiquadFilter();osc.type='triangle';osc.frequency.setValueAtTime(enoMidiFreq(midi),at);filter.type='lowpass';filter.frequency.setValueAtTime(4600,at);amp.gain.setValueAtTime(.0001,at);amp.gain.exponentialRampToValueAtTime(level,at+.018);amp.gain.exponentialRampToValueAtTime(.0001,at+Math.max(.06,duration));osc.connect(filter);filter.connect(amp);amp.connect(a.mix);osc.start(at);osc.stop(at+Math.max(.07,duration)+.025);}
    function arcadePlayInterval(semitones){const a=makeAudio();if(!a)return;const root=60+Math.floor(Math.random()*13),now=a.ctx.currentTime+.05;arcadeTone(root,now,.34,.11);arcadeTone(root+semitones,now+.43,.42,.11);}
    function arcadePlayChord(offsets){const a=makeAudio();if(!a)return;const root=48+Math.floor(Math.random()*13),now=a.ctx.currentTime+.05;offsets.forEach((offset,index)=>arcadeTone(root+offset,now,.9,.075));}
    function arcadeSaveStats(){const payload=JSON.stringify(arcadeStats);if(payload.length>12000){for(const key of Object.keys(arcadeStats))delete arcadeStats[key];}safeSet(ARCADE_STATS_KEY,JSON.stringify(arcadeStats));}
    function setupArcadeWindow(win){arcadeWindow=win;renderArcadeRecords(win);const bpm=win.querySelector('[data-arcade-bpm]');if(bpm)bpm.addEventListener('input',()=>{const out=win.querySelector('[data-arcade-bpm-out]');if(out)out.textContent=`${bpm.value} BPM`;});const canvas=win.querySelector('[data-arcade-canvas]');if(canvas){canvas.addEventListener('pointerdown',()=>canvas.focus({preventScroll:true}));canvas.addEventListener('keydown',arcadeKeydown);}}
    function renderArcadeRecords(win=arcadeWindow){const host=win?.querySelector('[data-arcade-records]');if(!host)return;host.replaceChildren();const rows=Object.entries(arcadeStats).filter(([key,value])=>['six','center','interval','chord'].includes(key)&&value&&typeof value==='object');if(!rows.length){const empty=document.createElement('span');empty.textContent='No sessions yet. Your best results will appear here.';host.append(empty);return;}rows.forEach(([key,value])=>{const card=document.createElement('div'),title=document.createElement('span'),score=document.createElement('b'),meta=document.createElement('small');title.textContent=arcadeLabels[key];score.textContent=`${Number(value.bestScore||0).toLocaleString()} pts`;meta.textContent=`${Number(value.bestAccuracy||0).toFixed(1)}% best accuracy · ${Number(value.sessions||0)} sessions`;card.append(title,score,meta);host.append(card);});}
    function setArcadeKeyGuide(win,mode){const host=win?.querySelector('[data-arcade-keyguide]');if(!host)return;host.replaceChildren();(mode==='center'?['A','S','W','D']:['A','S','D','←','↓','→']).forEach(key=>{const span=document.createElement('span');span.textContent=key;host.append(span);});}
    function selectArcadeMode(mode,win=arcadeWindow){if(!['six','center','interval','chord'].includes(mode))return;stopArcade(false);arcadeMode=mode;if(!win)return;win.querySelectorAll('[data-arcade-action^="select-"]').forEach(button=>button.classList.toggle('is-active',button.dataset.arcadeAction===`select-${mode}`));const rhythm=win.querySelector('[data-arcade-rhythm-setup]'),stage=win.querySelector('[data-arcade-stage]'),quiz=win.querySelector('[data-arcade-quiz]'),instructions=win.querySelector('[data-arcade-instructions]');if(rhythm)rhythm.hidden=mode==='interval'||mode==='chord';if(stage)stage.hidden=true;if(quiz)quiz.hidden=mode!=='interval'&&mode!=='chord';if(instructions)instructions.textContent=mode==='center'?'Four lanes travel inward toward the central target. Press A (left), S (down), W (up) or D (right) as each note reaches the centre.': 'Hit notes when they reach the target line. A/S/D use the first three lanes; ←/↓/→ use the last three.';setArcadeKeyGuide(win,mode);if(mode==='interval'||mode==='chord')startArcadeQuiz(mode,win);}
    function makeArcadeChart(minutes,bpm,difficulty,mode,key,scale){const cfg=arcadeDifficulty[difficulty]||arcadeDifficulty.normal,duration=minutes*60,beat=60/bpm,step=cfg.step*beat,total=Math.ceil(duration/step),notes=[],motifs=[[0,2,4,3,5,4,2,1],[0,3,2,5,4,1,3,2],[4,3,1,2,5,3,0,2],[0,4,2,3,1,5,4,2]],degrees=enoScales[scale]||enoScales.minor,motif=motifs[Math.floor(Math.random()*motifs.length)];let priorLane=-1,phraseOffset=0;for(let i=0;i<total;i++){const at=i*step;if(at>duration)break;const beatIndex=Math.floor(at/beat),inBar=beatIndex%8,degree=motif[inBar]+(phraseOffset%2?1:0);if(Math.random()>cfg.probability)continue;let lane;if(Math.random()<.17)lane=Math.floor(Math.random()*(mode==='center'?4:6));else{lane=(degree+Math.floor(phraseOffset/2))%(mode==='center'?4:6);if(lane===priorLane&&Math.random()<.6)lane=(lane+1+Math.floor(Math.random()*(mode==='center'?3:5)))%(mode==='center'?4:6);}priorLane=lane;notes.push({time:at,lane,midi:48+key+degrees[degree%degrees.length]+(Math.floor(degree/degrees.length)*12)+Math.floor(Math.random()*2)*12,hit:false,missed:false});if(inBar===7)phraseOffset++;}return{mode,minutes,bpm,duration,travel:cfg.travel,window:cfg.window,notes,score:0,hits:0,misses:0,streak:0,bestStreak:0,start:0,elapsed:0,lastTap:0,finished:false};}
    function arcadeUpdateHud(win,game){const accuracy=game.hits+game.misses?game.hits/(game.hits+game.misses)*100:100;const set=(selector,value)=>{const node=win?.querySelector(selector);if(node)node.textContent=value;};set('[data-arcade-score]',game.score.toLocaleString());set('[data-arcade-accuracy]',`${accuracy.toFixed(1)}%`);set('[data-arcade-streak]',String(game.streak));set('[data-arcade-time]',`${String(Math.floor(Math.max(0,game.duration-game.elapsed)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,game.duration-game.elapsed)%60)).padStart(2,'0')}`);}
    function arcadeDraw(game,canvas){if(!canvas?.isConnected)return;const rect=canvas.getBoundingClientRect(),width=Math.max(320,Math.floor(rect.width||960)),height=Math.max(260,Math.floor(rect.height||500)),dpr=Math.min(2,window.devicePixelRatio||1);if(canvas.width!==Math.floor(width*dpr)||canvas.height!==Math.floor(height*dpr)){canvas.width=Math.floor(width*dpr);canvas.height=Math.floor(height*dpr);}const ctx=canvas.getContext('2d');if(!ctx)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);const center=width/2;ctx.fillStyle='#081321';ctx.fillRect(0,0,width,height);ctx.strokeStyle='rgba(102,222,226,.12)';ctx.lineWidth=1;for(let y=20;y<height;y+=32){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(width,y);ctx.stroke();}const colors=['#58e4dc','#ff72b9','#a78bfa','#ffc16f','#75baff','#b9ec8f'];
      if(game.mode==='center'){const cx=center,cy=height*.5,radius=Math.min(width*.36,height*.38),starts=[[cx-radius,cy],[cx,cy+radius],[cx,cy-radius],[cx+radius,cy]],labels=['A','S','W','D'];for(let lane=0;lane<4;lane++){ctx.strokeStyle=colors[lane]+'55';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(starts[lane][0],starts[lane][1]);ctx.lineTo(cx,cy);ctx.stroke();ctx.beginPath();ctx.arc(starts[lane][0],starts[lane][1],17,0,Math.PI*2);ctx.stroke();ctx.fillStyle=colors[lane];ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText(labels[lane],starts[lane][0],starts[lane][1]+4);}ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(cx,cy,29,0,Math.PI*2);ctx.stroke();ctx.fillStyle='rgba(255,255,255,.08)';ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 9px monospace';ctx.fillText('HIT',cx,cy+3);
        for(const note of game.notes){if(note.hit||note.missed)continue;const remaining=note.time-game.elapsed;if(remaining>game.travel||remaining<-.1)continue;const progress=1-Math.max(0,remaining)/game.travel,start=starts[note.lane],x=start[0]+(cx-start[0])*progress,y=start[1]+(cy-start[1])*progress;ctx.fillStyle=colors[note.lane];ctx.beginPath();ctx.arc(x,y,9,0,Math.PI*2);ctx.fill();}
      }else{const lanes=6,gap=width/(lanes+1),hitY=height*.82,top=height*.1;for(let lane=0;lane<lanes;lane++){const x=gap*(lane+1);ctx.fillStyle='rgba(255,255,255,.025)';ctx.fillRect(x-gap*.43,top,gap*.86,hitY-top+20);ctx.strokeStyle=colors[lane]+'88';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,hitY+14);ctx.stroke();ctx.fillStyle=colors[lane];ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText(['A','S','D','←','↓','→'][lane],x,height-18);ctx.strokeStyle='#fff';ctx.beginPath();ctx.arc(x,hitY,13,0,Math.PI*2);ctx.stroke();}for(const note of game.notes){if(note.hit||note.missed)continue;const remaining=note.time-game.elapsed,y=hitY-(remaining/game.travel)*(hitY-top);if(y<top-20||y>hitY+20)continue;const x=gap*(note.lane+1);ctx.fillStyle=colors[note.lane];ctx.shadowColor=colors[note.lane];ctx.shadowBlur=11;ctx.fillRect(x-13,y-7,26,14);ctx.shadowBlur=0;}}
    }
    function arcadeFinish(win=arcadeWindow){const game=arcadeGame;if(!game||game.finished)return;game.finished=true;cancelAnimationFrame(arcadeRAF);arcadeRAF=0;const acc=game.hits+game.misses?game.hits/(game.hits+game.misses)*100:0;const prior=arcadeStats[game.mode]||{};arcadeStats[game.mode]={bestScore:Math.max(Number(prior.bestScore)||0,game.score),bestAccuracy:Math.max(Number(prior.bestAccuracy)||0,acc),sessions:(Number(prior.sessions)||0)+1,bestStreak:Math.max(Number(prior.bestStreak)||0,game.bestStreak)};arcadeSaveStats();const stage=win?.querySelector('[data-arcade-stage]'),results=win?.querySelector('[data-arcade-results]'),title=win?.querySelector('[data-arcade-result-title]'),score=win?.querySelector('[data-arcade-result-score]'),accuracy=win?.querySelector('[data-arcade-result-accuracy]'),best=win?.querySelector('[data-arcade-result-best]'),copy=win?.querySelector('[data-arcade-result-copy]');if(stage)stage.hidden=true;if(results)results.hidden=false;if(title)title.textContent=game.mode==='center'?'Center Guard complete': 'Rhythm Grid complete';if(score)score.textContent=game.score.toLocaleString();if(accuracy)accuracy.textContent=`${acc.toFixed(1)}%`;if(best)best.textContent=String(game.bestStreak);if(copy)copy.textContent=`${game.hits.toLocaleString()} notes hit · ${game.misses.toLocaleString()} misses · ${game.minutes} minute session. The chart was generated from ${enoKeys[Number(win?.querySelector('[data-arcade-key]')?.value)||0]}-rooted scale material.`;const start=win?.querySelector('[data-arcade-action="start"]'),stop=win?.querySelector('[data-arcade-action="stop"]');if(start)start.disabled=false;if(stop)stop.disabled=true;const status=win?.querySelector('[data-arcade-status]');if(status)status.textContent=`Complete · ${acc.toFixed(1)}% accuracy`;renderArcadeRecords(win);}
    function stopArcade(showStatus=true){if(arcadeRAF){cancelAnimationFrame(arcadeRAF);arcadeRAF=0;}if(arcadeGame&&!arcadeGame.finished&&showStatus){const win=arcadeWindow,status=win?.querySelector('[data-arcade-status]');if(status)status.textContent='Session stopped.';}if(arcadeGame){arcadeGame.finished=true;}arcadeGame=null;if(arcadeQuiz){arcadeQuiz=null;}if(arcadeWindow){const stage=arcadeWindow.querySelector('[data-arcade-stage]'),results=arcadeWindow.querySelector('[data-arcade-results]');if(stage)stage.hidden=true;if(results&&showStatus)results.hidden=true;const start=arcadeWindow.querySelector('[data-arcade-action="start"]'),stop=arcadeWindow.querySelector('[data-arcade-action="stop"]');if(start)start.disabled=false;if(stop)stop.disabled=true;}}
    function arcadeFrame(now){const game=arcadeGame,win=arcadeWindow;if(!game||game.finished||!win?.isConnected)return;game.elapsed=Math.min(game.duration,(now-game.start)/1000);for(const note of game.notes){if(!note.hit&&!note.missed&&game.elapsed>note.time+game.window){note.missed=true;game.misses++;game.streak=0;}}const canvas=win.querySelector('[data-arcade-canvas]');arcadeDraw(game,canvas);arcadeUpdateHud(win,game);if(game.elapsed>=game.duration){arcadeFinish(win);return;}arcadeRAF=requestAnimationFrame(arcadeFrame);}
    function startArcade(win=arcadeWindow){if(!win)return;stopArcade(false);const minutes=clamp(Number(win.querySelector('[data-arcade-minutes]')?.value)||3,2,4),bpm=clamp(Number(win.querySelector('[data-arcade-bpm]')?.value)||108,70,180),difficulty=win.querySelector('[data-arcade-difficulty]')?.value||'normal',key=clamp(Number(win.querySelector('[data-arcade-key]')?.value)||0,0,11),scale=win.querySelector('[data-arcade-scale]')?.value||'minor';const game=makeArcadeChart(minutes,bpm,difficulty,arcadeMode,key,scale);arcadeGame=game;const quiz=win.querySelector('[data-arcade-quiz]'),stage=win.querySelector('[data-arcade-stage]'),results=win.querySelector('[data-arcade-results]');if(quiz)quiz.hidden=true;if(stage)stage.hidden=false;if(results)results.hidden=true;const start=win.querySelector('[data-arcade-action="start"]'),stop=win.querySelector('[data-arcade-action="stop"]');if(start)start.disabled=true;if(stop)stop.disabled=false;const status=win.querySelector('[data-arcade-status]');if(status)status.textContent=`${arcadeLabels[arcadeMode]} · ${minutes} min · ${bpm} BPM · ${difficulty.replace('-',' ')}`;setArcadeKeyGuide(win,arcadeMode);const canvas=win.querySelector('[data-arcade-canvas]');if(canvas)canvas.focus({preventScroll:true});makeAudio()?.ctx?.resume?.().catch(()=>{});game.start=performance.now();arcadeUpdateHud(win,game);arcadeRAF=requestAnimationFrame(arcadeFrame);}
    function arcadeKeydown(e){const game=arcadeGame;if(!game||game.finished||!arcadeWindow?.isConnected)return;const tag=e.target?.tagName?.toLowerCase();if(['input','select','textarea'].includes(tag)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'){e.preventDefault();stopArcade(true);return;}const key=e.key.length===1?e.key.toLowerCase():e.key;const laneMap=game.mode==='center'?{a:0,s:1,w:2,d:3}:{a:0,s:1,d:2,ArrowLeft:3,ArrowDown:4,ArrowRight:5};if(!Object.prototype.hasOwnProperty.call(laneMap,key))return;e.preventDefault();const lane=laneMap[key],now=(performance.now()-game.start)/1000;let best=null,bestDelta=Infinity;for(const note of game.notes){if(note.hit||note.missed||note.lane!==lane)continue;const delta=Math.abs(note.time-now);if(delta<bestDelta){best=note;bestDelta=delta;}}if(best&&bestDelta<=game.window){best.hit=true;game.hits++;game.streak++;game.bestStreak=Math.max(game.bestStreak,game.streak);const ratio=bestDelta/game.window;game.score+=ratio<.28?300:ratio<.62?200:100;arcadeTone(best.midi,0,.12,.07);arcadeUpdateHud(arcadeWindow,game);}else{game.streak=0;game.misses++;arcadeUpdateHud(arcadeWindow,game);}}
    function startArcadeQuiz(mode,win=arcadeWindow){if(!win)return;stopArcade(false);makeAudio()?.ctx?.resume?.().catch(()=>{});arcadeMode=mode;const quiz={mode,attempts:0,correct:0,current:null,finished:false};arcadeQuiz=quiz;const host=win.querySelector('[data-arcade-answer-grid]');if(!host)return;host.replaceChildren();const type=win.querySelector('[data-arcade-quiz-kind]');if(type)type.textContent=mode==='interval'?'INTERVAL RECOGNITION':'CHORD RECOGNITION';const q=win.querySelector('[data-arcade-question]');if(q)q.textContent=mode==='interval'?'Which interval did you hear?':'Which chord quality did you hear?';win.querySelector('[data-arcade-quiz]')?.removeAttribute('hidden');win.querySelector('[data-arcade-stage]')?.setAttribute('hidden','');win.querySelector('[data-arcade-results]')?.setAttribute('hidden','');quizNext(win);}
    function quizPlay(win=arcadeWindow){if(!arcadeQuiz?.current)return;if(arcadeQuiz.mode==='interval')arcadePlayInterval(arcadeQuiz.current.semitones);else arcadePlayChord(arcadeQuiz.current.offsets);}
