      const level=e.target.dataset.enoMixerLevel;if(level!==undefined){state.levels[+level]=clamp(Number(e.target.value)/100,0,1);const out=e.target.parentElement.querySelector('output');if(out)out.textContent=`${e.target.value}%`;persist();return;}
      const pan=e.target.dataset.enoMixerPan;if(pan!==undefined){state.pan[+pan]=clamp(Number(e.target.value)/100,-1,1);const out=e.target.parentElement.querySelector('output');if(out)out.textContent=`${e.target.value}%`;persist();return;}
      if(e.target.matches('[data-eno-piano-velocity]')){state.pianoVelocity=clamp(Number(e.target.value)||78,10,100);const out=$e('[data-eno-piano-velocity-out]');if(out)out.textContent=`${state.pianoVelocity}%`;persist();return;}
