        if(songs.length)outputs.push({type:'echonoise/songbook',title:`Echonoise Songbook (${songs.length} songs)`,data:{format:'curioid-echonoise-songbook',version:1,songs:songs.slice(-80)},metadata:{songCount:songs.length,sequencer:'pattern-banks+arrangement+piano-roll'}});
