          songs.forEach(song=>{if(song?.id)known.add(`${sourceExperience}:${String(song.id)}`);if(song?.importedFrom?.experienceId&&song?.importedFrom?.songId)known.add(`${song.importedFrom.experienceId}:${song.importedFrom.songId}`);});
          let duplicateCount=0;const unique=[];
          for(const song of incoming){const sourceId=clean(song.id||`anonymous-${JSON.stringify(song).length}`,120),fingerprint=`${sourceExperience}:${sourceId}`;if(known.has(fingerprint)){duplicateCount++;continue;}known.add(fingerprint);unique.push({song,sourceId});}
          const capacity=Math.max(0,80-songs.length),accepted=unique.slice(0,capacity),capacitySkipped=unique.length-accepted.length;
          const cleaned=accepted.map(({song,sourceId})=>({...sanitizeSong(song),id:'song-import-'+Date.now().toString(36)+'-'+uid(),importedFrom:{experienceId:sourceExperience,songId:sourceId},name:clean(song.name||'Imported session',64)}));
