    function deleteLayer(){const i=layers.findIndex(l=>l.id===activeLayerId);if(i<0){note('Select a layer before deleting it.');return;}const active=layers[i];if(!window.confirm(`Delete “${active.name||'this layer'}”? You can undo this action.`))return;checkpoint('Delete layer');if(layers.length<=1){getCtx(current()).clearRect(0,0,doc.width,doc.height);if(current()?.mask)getCtx({canvas:current().mask}).clearRect(0,0,doc.width,doc.height);hasArtwork=false;markChanged('Cleared the only layer');return;}maskScratch.delete(active.id);layers.splice(i,1);activeLayerId=layers[Math.max(0,i-1)].id;updateLayerList();markChanged(`Deleted ${active.name||'layer'}`);}
