    async function openProjectFile(file){
      if(!file)return;
      if(projectImportBusy)throw new Error('A UMBRA project replacement is already in progress. Wait for it to finish before opening another file.');
      if(file.size>100*1024*1024)throw new Error('Project file exceeds the 100 MB safety limit.');
      setProjectImportBusy(true);
      const importEpoch=++umbraImportEpoch;
      try{
        const data=JSON.parse(await file.text());
        const previous=serialize(),historyLength=history.length,openingEpoch=umbraEditEpoch;
        const safetyBackup=await kernelSaveAdapterSafetyBackup('umbra-os',CurioidKernel.getAdapter('umbra-os'),'umbra/project');
        if(disposed||importEpoch!==umbraImportEpoch)throw new Error('This UMBRA import was superseded before it could be applied. The current document was left unchanged.');
        if(umbraEditEpoch!==openingEpoch)throw new Error('The current UMBRA document changed while its recovery copy was being saved. No replacement was applied. Your current document is still open; retry when editing has stopped.');
        checkpoint('Open UMBRA project');userTouched=true;clearTimeout(autosaveTimer);
        try{
          await restoreData(data,{expectedEditEpoch:openingEpoch});doc.name=safeName(file.name.replace(/\.(?:umbra|json)$/i,''));
          markChanged('Project opened · local recovery queued');
          if(safetyBackup)note(`Project opened. Previous document saved and verified in Browser Vault: ${safetyBackup.name}.`);
        }catch(error){
          clearTimeout(autosaveTimer);
          try{await restoreData(previous);dirty=false;history.length=historyLength;renderHistory();}
          catch(rollbackError){throw new Error(`${error.message} The previous document could not be restored in memory: ${rollbackError.message}`);}
          throw error;
        }
      }finally{setProjectImportBusy(false);}
    }
