    const uaResample=(points,count)=>{if(points.length<2)return points.slice();const total=uaLength(points);if(total<.001)return points.slice(0,count);const out=[];let segment=1,walk=0;for(let i=0;i<count;i++){const wanted=total*i/Math.max(1,count-1);while(segment<points.length-1&&walk+uaDist(points[segment-1],points[segment])<wanted){walk+=uaDist(points[segment-1],points[segment]);segment++;}const a=points[segment-1],b=points[segment],len=uaDist(a,b)||1,t=uaClamp((wanted-walk)/len,0,1);out.push({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});}return out;};
