    const uaFitScore=points=>{if(points.length<18||uaLength(points)<160)return 0;const cx=points.reduce((s,p)=>s+p.x,0)/points.length,cy=points.reduce((s,p)=>s+p.y,0)/points.length,radii=points.map(p=>Math.hypot(p.x-cx,p.y-cy)),r=radii.reduce((s,n)=>s+n,0)/radii.length;if(r<60)return 0;const deviation=Math.sqrt(radii.reduce((s,n)=>s+(n-r)*(n-r),0)/radii.length)/r;let angle=0;for(let i=1;i<points.length;i++){const a=Math.atan2(points[i-1].y-cy,points[i-1].x-cx),b=Math.atan2(points[i].y-cy,points[i].x-cx);let d=b-a;while(d>Math.PI)d-=Math.PI*2;while(d<-Math.PI)d+=Math.PI*2;angle+=d;}const sweep=Math.min(Math.PI*2,Math.abs(angle));const gap=uaDist(points[0],points[points.length-1]);const closure=uaClamp(1-gap/(r*.38),0,1),coverage=uaClamp(sweep/(Math.PI*2),0,1),roundness=uaClamp(1-deviation*2.4,0,1);return Math.round(100*roundness*(.78+.22*closure)*coverage*10)/10;};
