    function uaShowCongratulations(message){if(!uaPanel)return;let layer=uaPanel.querySelector('[data-ua-congratulations]');if(!layer){layer=document.createElement('section');layer.className='ua-congratulations';layer.dataset.uaCongratulations='';layer.hidden=true;layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-labelledby','ua-congratulations-title');const card=document.createElement('div'),eyebrow=document.createElement('small'),title=document.createElement('h3'),copy=document.createElement('p'),button=document.createElement('button');eyebrow.textContent='UMBRA ARCADE / ROUND COMPLETE';title.id='ua-congratulations-title';title.textContent='CONGRATULATIONS!';copy.dataset.uaCongratulationsCopy='';button.type='button';button.textContent='OK';card.append(eyebrow,title,copy,button);layer.append(card);if(getComputedStyle(uaPanel).position==='static')uaPanel.style.position='relative';uaPanel.append(layer);button.addEventListener('click',()=>{layer.hidden=true;uaRetry();uaCanvas?.focus?.();});}layer.querySelector('[data-ua-congratulations-copy]').textContent=String(message||'You completed the challenge.').slice(0,260);layer.hidden=false;layer.querySelector('button').focus();}
    function uaSaveBest(score,won=false){uaLastScore=score;uaScore=score;if(score>(uaBestScores[uaGame]??-1)){uaBestScores[uaGame]=score;if(uaBestWritable){try{localStorage.setItem(UA_STORE_KEY,JSON.stringify(uaBestScores));}catch(_){uaBestWritable=false;}}}uaUpdateUi();if(score>=90){uaSay('Beautiful work. You crossed the 90% line!');uaBurst();uaBeep();}else uaSay(score>=75?'Solid run. Have another go and beat that best.':'A little chaotic. Which is exactly how good arcade stories start.');if(won)uaShowCongratulations(`${uaGames[uaGame].title} cleared with ${score.toFixed(1)}%. Press OK to play a fresh round.`);}
    function uaBeep(){if(!uaSound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;uaAudio=uaAudio||new AC();if(uaAudio.state==='suspended')uaAudio.resume();const now=uaAudio.currentTime;[660,880,1100].forEach((hz,i)=>{const o=uaAudio.createOscillator(),g=uaAudio.createGain();o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(.0001,now+i*.075);g.gain.exponentialRampToValueAtTime(.045,now+i*.075+.012);g.gain.exponentialRampToValueAtTime(.0001,now+i*.075+.13);o.connect(g);g.connect(uaAudio.destination);o.start(now+i*.075);o.stop(now+i*.075+.15);});}catch(_){}}
    function uaBurst(){for(let i=0;i<34;i++)uaParticles.push({x:480,y:280,vx:(Math.random()-.5)*7,vy:-Math.random()*6-1,life:55+Math.random()*25,size:2+Math.random()*4});uaEnsureLoop();}
