    function uaClearBoard(){uaCtx.clearRect(0,0,UA_W,UA_H);uaCtx.fillStyle='#0b111a';uaCtx.fillRect(0,0,UA_W,UA_H);uaCtx.save();uaCtx.strokeStyle='rgba(180,197,225,.055)';uaCtx.lineWidth=1;for(let x=0;x<=UA_W;x+=40){uaCtx.beginPath();uaCtx.moveTo(x,0);uaCtx.lineTo(x,UA_H);uaCtx.stroke();}for(let y=0;y<=UA_H;y+=40){uaCtx.beginPath();uaCtx.moveTo(0,y);uaCtx.lineTo(UA_W,y);uaCtx.stroke();}uaCtx.restore();}
