    function uaRender(){if(!uaCtx)return;uaDrawBase();if(uaPath.length>1&&!(uaGame==='mirror'&&uaPhase==='draw'))uaLine(uaPath,'#eaf1ff',5);if(uaGame==='split'&&uaPath.length>1)uaLine([uaPath[0],uaPath[uaPath.length-1]],'#ff8bba',4);if(uaGame==='fit'&&uaPath.length>2&&uaPhase==='done')uaClosed(uaPath,'rgba(216,255,79,.12)');if(uaGame==='bridge'&&uaPhase==='draw'&&uaPath.length>1)uaLine(uaPath,'#eaf1ff',6);if(uaPhase==='done'&&uaGame==='mirror'&&uaPath.length>1)uaLine(uaPath,'#ff8bba',5);if(uaScore!==null){uaText(`${uaScore.toFixed(1)}%`,480,62,20,uaScore>=90?'#d8ff4f':'#e4eaf6','center');}for(let i=uaParticles.length-1;i>=0;i--){const p=uaParticles[i];uaCtx.globalAlpha=uaClamp(p.life/60,0,1);uaCtx.fillStyle=i%2?'#d8ff4f':'#ff8bba';uaCtx.fillRect(p.x,p.y,p.size,p.size);uaCtx.globalAlpha=1;} }
