        if(n.type!=='file'||!n.asset)continue;
        let file;
        try{file=await getAsset(n.asset);}
        catch(error){unavailable.push(`${n.fileName||n.title}: ${String(error?.message||error).slice(0,140)}`);continue;}
        if(!file){unavailable.push(`${n.fileName||n.title}: attachment bytes are unavailable.`);continue;}
        if(total+file.size>8*1024*1024){tooLarge.push(n.fileName||n.title);continue;}
        const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=()=>reject(r.error||new Error('Aether could not encode an attachment for export.'));r.readAsDataURL(file);});
