      const target=workspace;
      if(!window.confirm(`Delete project “${target.name}” and its ${(target.nodes||[]).length} node(s) and attachments? This cannot be undone.`))return;
      clearTimeout(saveTimer);
      // Save the active record first, then commit the index change in the storage
      // mode that currently owns the authoritative workspace snapshot.
      await persistWorkspace();
      const remaining=workspaces.filter(item=>item.id!==target.id);
      try{
        if(dbMode==='LOCAL FALLBACK')writeWorkspaceFallback(remaining);
        else await idbDeleteWorkspaceIfRevision(target.id,curioidReadStorageRevision(target,'Aether workspace selected for deletion'));
      }catch(error){if(error?.name==='AetherRevisionConflict')workspaceConflict=true;if(error?.name==='AetherStorageIntegrityError'){workspaceConflict=true;workspaceStorageReadOnly=true;updateStorageLabels();}say(error.message||'Workspace deletion could not be committed.');return;}
      workspaces=remaining;
      workspace=safeJsonClone(workspaces.slice().sort((a,b)=>(b.updated||0)-(a.updated||0))[0]);
      currentId=workspace.id;selectedId=null;connectSource=null;autoEdges=[];clearAetherHistory();
      refreshWorkspaceSelect();renderNodes();updateViewFromSaved();queueGravity();selectNode(null);
