        if(current!==previousRaw){say(`Saving ${key} encountered a cross-tab conflict. The newer stored value was left untouched. Reload AURA before editing.`);return false;}
        say(`Saving ${key} failed. Its previous value remains intact: ${String(error?.message||error).slice(0,150)}`);return false;
