        if(!saveStratoRecord(nextRecord)){loading.status='The starting word could not be permanently recorded. No pyramid was started. Check storage and try again.';loading.loading=false;loading.finished=true;arcadeStates.set('stratoladder',loading);renderArcade(win);return;}
