    function resumeQuotaPanic(win){const state=arcadeStates.get('quota-panic');if(!state||state.finished||state.loading||state.running||activeArcadeMode!=='quota-panic')return;state.running=true;const tick=()=>{if(!state.running||state.finished||!win?.isConnected||activeArcadeMode!=='quota-panic'){state.running=false;return;}state.timeLeft=Math.max(0,state.timeLeft-1);if(state.timeLeft<=0){finishQuotaPanic(win,'TIME EXPIRED. The submission window has closed.');return;}renderQuotaPanic(win);scheduleArcade(tick,1000);};scheduleArcade(tick,1000);}
